/// <summary>
/// designed by AVANADE
/// </summary>
[DataContractAttribute]
class AVAQuickCopyContract
{
    container   recordCon;
    RecordSortedList    records;

}

Method.Source:
public container parmRecordCon(container _recordCon = recordCon)
{
    recordCon = _recordCon;
    return recordCon;
}

public RecordSortedList parmRecords(RecordSortedList _records = records)
{
    records = _records;
    return records;
}
